#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int Mod = 998244353;
const int MAX = 500;

ll fac[MAX + 1], finv[MAX + 1], inv[MAX + 1];

void init_fac() {
    fac[0] = fac[1] = finv[0] = finv[1] = inv[1] = 1;
    for (int i = 2; i <= MAX; i++) {
        fac[i] = fac[i - 1] * i % Mod;
        inv[i] = Mod - inv[Mod % i] * (Mod / i) % Mod;
        finv[i] = finv[i - 1] * inv[i] % Mod;
    }
}

ll ModCombination(int n, int k) {
    if (n < k) return 0;
    ll ret = 1;
    while (n > 0 || k > 0) {
        ret = ret * fac[n % Mod] % Mod * finv[k % Mod] % Mod * finv[(n - k) % Mod] % Mod;
        n /= Mod;
        k /= Mod;
    }
    return ret;
}

int main() {
    init_fac();
    int n, x;
    cin >> n >> x;

    ll pow[501][501];
    for (ll i = 0; i < 501; i++) {
        pow[i][0] = 1;
        for (int j = 0; j < 500; j++) {
            pow[i][j + 1] = pow[i][j] * i % Mod;
        }
    }

    ll dp[501][501] = {0};
    for (int i = 2; i <= n; i++) {
        int jj = min(x, i - 1);
        for (int j = 1; j <= jj; j++) {
            dp[i][j] = (pow[j][i] - pow[j - 1][i]) % Mod;
        }
    }

    for (int i = 2; i <= n; i++) {
        for (int j = 1; j <= x; j++) {
            if (dp[i][j] == 0) continue;
            for (int k = 0; k <= n - i; k++) {
                int nj = j + i + k - 1;
